// Loader of the Rust engine compiled to WebAssembly (crate office-wasm, generated by wasm-bindgen
// into office_wasm.js / office_wasm_bg.wasm next to this file by scripts/build-web.ps1).
// Imported by .NET as the JS module "nexolume-engine" (OfficeBridge.Browser.BrowserOfficeTransport).
//
// Errors: the engine throws JS Errors whose message is "Code: detail" (HostError in office-wasm);
// BrowserOfficeTransport maps them to OfficeTransportException(code). A Rust panic aborts the
// WebAssembly instance (panic = "abort"): its state can no longer be trusted, so every later call
// fails with "EngineCrashed" instead of returning possibly corrupt documents.
import init, * as wasm from './office_wasm.js';

let ready = null;
let crashed = null;

export function initialize() {
  ready ??= init({ module_or_path: new URL('./office_wasm_bg.wasm', import.meta.url) }).then(() => {
    if (wasm.protocolVersion() !== 1) throw new Error(`EngineUnavailable: protocole ${wasm.protocolVersion()} non pris en charge`);
  });
  return ready;
}

function guard(call) {
  if (crashed !== null) throw new Error(`EngineCrashed: ${crashed}`);
  try {
    return call();
  } catch (error) {
    if (error instanceof WebAssembly.RuntimeError) {
      let detail = null;
      try { detail = wasm.lastPanic(); } catch { /* the instance may not answer any more */ }
      crashed = detail ?? error.message;
      console.error('[Nexolume] Le moteur WebAssembly s’est arrêté :', crashed);
      throw new Error(`EngineCrashed: ${crashed}`);
    }
    throw error;
  }
}

export const create = () => guard(() => wasm.create());
export const destroy = (handle) => guard(() => wasm.destroy(handle));
export const execute = (handle, request) => guard(() => wasm.execute(handle, request));
export const openEngines = () => guard(() => wasm.openEngines());
export const isCrashed = () => crashed !== null;
